import React from 'react';
import { TextField, MenuItem, Box } from '@mui/material';
import { formats, bitrates } from '../constants';

const OutputSettings = ({ format, bitrate, onFormatChange, onBitrateChange }) => (
  <Box sx={{ display: 'flex', flexDirection: { xs: 'column', sm: 'row' }, gap: { xs: 0, sm: 2 } }}>
    <TextField
      select
      label="Output Format"
      value={format}
      onChange={onFormatChange}
      fullWidth
      margin="normal"
    >
      {formats.map((option) => (
        <MenuItem key={option.title} value={option}>
          {option.title}
        </MenuItem>
      ))}
    </TextField>
    <TextField
      select
      label="Output Bitrate"
      value={bitrate}
      onChange={onBitrateChange}
      disabled={format.extension === 'flac'}
      fullWidth
      margin="normal"
    >
      {bitrates.map((option) => (
        <MenuItem key={option.title} value={option}>
          {option.title}
        </MenuItem>
      ))}
    </TextField>
  </Box>
);

export default OutputSettings;
