import React from 'react';
import { TextField, MenuItem } from '@mui/material';
import { roomTypes } from '../constants';

const RoomTypeSelector = ({ value, onChange }) => (
  <TextField
    select
    label="Room Type"
    value={value}
    onChange={onChange}
    fullWidth
    margin="normal"
  >
    {roomTypes.map((option) => (
      <MenuItem key={option.title} value={option}>
        {`${option.title} (${option.index})`}
      </MenuItem>
    ))}
  </TextField>
);

export default RoomTypeSelector;
