import React, { useState } from 'react'
import { Box, Typography, Dialog, DialogTitle, DialogContent, IconButton, TextField, keyframes, useTheme } from '@mui/material'
import CheckCircleIcon from '@mui/icons-material/CheckCircle'
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked'
import ErrorOutlineIcon from '@mui/icons-material/ErrorOutline'
import CloseIcon from '@mui/icons-material/Close'

const pulse = keyframes`
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
`

const STEPS = [
  { key: 'wav', label: 'Converting audio to WAV' },
  { key: 'dsp', label: 'Applying DSP effects' },
  { key: 'encode', label: 'Converting audio to output format' },
]

const ProcessingSteps = ({ step, logs }) => {
  const theme = useTheme()
  const [logsOpen, setLogsOpen] = useState(false)

  const stepStatus = (key) => {
    const order = ['wav', 'dsp', 'encode']
    const curIdx = order.indexOf(step)
    const stepIdx = order.indexOf(key)
    if (step === 'error') return stepIdx < curIdx ? 'done' : 'pending'
    if (step === 'done') return 'done'
    if (stepIdx < curIdx) return 'done'
    if (stepIdx === curIdx) return 'active'
    return 'pending'
  }

  const renderIcon = (status) => {
    if (status === 'done') return <CheckCircleIcon sx={{ fontSize: 18, color: 'success.main' }} />
    if (status === 'active') return (
      <Box
        component="span"
        sx={{
          width: 12,
          height: 12,
          borderRadius: '50%',
          bgcolor: 'primary.main',
          display: 'inline-block',
          animation: `${pulse} 1.2s ease-in-out infinite`,
        }}
      />
    )
    return <RadioButtonUncheckedIcon sx={{ fontSize: 18, color: theme.palette.text.disabled }} />
  }

  const hasLogs = logs && logs.trim().length > 0

  if (!step || step === 'idle') return null

  return (
    <Box sx={{ mt: 2 }}>
      {STEPS.map((s) => {
        const status = stepStatus(s.key)
        return (
          <Box
            key={s.key}
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: 1,
              py: 0.6,
              opacity: status === 'pending' ? 0.45 : 1,
            }}
          >
            {renderIcon(status)}
            <Typography
              variant="body2"
              sx={{
                color: status === 'active' ? 'primary.main' : 'text.primary',
                fontWeight: status === 'active' ? 500 : 400,
              }}
            >
              {s.label}
            </Typography>
          </Box>
        )
      })}

      {step === 'error' && (
        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, py: 0.6 }}>
          <ErrorOutlineIcon sx={{ fontSize: 18, color: 'error.main' }} />
          <Typography variant="body2" color="error.main">
            Processing failed
          </Typography>
        </Box>
      )}

      {hasLogs && (
        <Box sx={{ mt: 1 }}>
          <Box
            onClick={() => setLogsOpen(true)}
            sx={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: 0.3,
              cursor: 'pointer',
              color: 'text.secondary',
              '&:hover': { color: 'text.primary' },
            }}
          >
            <Typography variant="caption" sx={{ fontSize: '0.7rem', userSelect: 'none' }}>
              Open processing logs
            </Typography>
          </Box>
        </Box>
      )}

      <Dialog
        open={logsOpen}
        onClose={() => setLogsOpen(false)}
        maxWidth={false}
        fullWidth
        PaperProps={{ sx: { height: '90vh', maxHeight: '90vh' } }}
      >
        <DialogTitle sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', py: 1.5 }}>
          <Typography variant="body2" sx={{ fontWeight: 500 }}>Technical logs</Typography>
          <IconButton size="small" onClick={() => setLogsOpen(false)}>
            <CloseIcon fontSize="small" />
          </IconButton>
        </DialogTitle>
        <DialogContent dividers sx={{ p: 0 }}>
          <TextField
            variant="standard"
            multiline
            value={logs}
            slotProps={{
              htmlInput: {
                readOnly: true,
                style: {
                  fontFamily: '"Cascadia Code", "Fira Code", "JetBrains Mono", monospace',
                  fontSize: '0.75rem',
                  lineHeight: 1.5,
                  padding: 16,
                  height: '100%',
                },
              },
            }}
            fullWidth
            sx={{ height: '100%', '& .MuiInputBase-root': { height: '100%', alignItems: 'flex-start' } }}
          />
        </DialogContent>
      </Dialog>
    </Box>
  )
}

export default ProcessingSteps
