import React, { useRef, useState, useEffect } from 'react'
import { Box, Typography, IconButton } from '@mui/material'
import AudioFileIcon from '@mui/icons-material/AudioFile'
import CloseIcon from '@mui/icons-material/Close'
import { formatSize, formatTime } from '../utils'

const chLabel = (n) => n === 1 ? 'Mono' : n === 2 ? 'Stereo' : `${n} ch`

const FileUploader = ({ file, meta, onFileSelect }) => {
  const [dragOver, setDragOver] = useState(false)
  const fileInputRef = useRef(null)

  const handleFileChange = (event) => {
    if (event.target.files[0]) onFileSelect(event.target.files[0])
  }

  const handleDrop = (e) => {
    e.preventDefault()
    setDragOver(false)
    if (e.dataTransfer.files[0]) onFileSelect(e.dataTransfer.files[0])
  }

  const handleDragOver = (e) => {
    e.preventDefault()
    setDragOver(true)
  }

  const handleDragLeave = () => setDragOver(false)

  useEffect(() => {
    const handlePaste = (e) => {
      const files = e.clipboardData.files
      if (files.length > 0) {
        const f = files[0]
        if (f.type.startsWith('audio/')) onFileSelect(f)
      }
    }
    document.addEventListener('paste', handlePaste)
    return () => document.removeEventListener('paste', handlePaste)
  }, [onFileSelect])

  if (file) {
    return (
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
        <AudioFileIcon sx={{ fontSize: 36, color: 'primary.main', opacity: 0.7 }} />
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="body2" noWrap sx={{ fontWeight: 500 }}>
            {file.name}
          </Typography>
          <Typography variant="caption" color="text.secondary">
            {formatSize(file.size)}
            {meta && (
              <>
                {' · '}
                {formatTime(meta.duration)}
                {' · '}
                {meta.sampleRate} Hz
                {' · '}
                {chLabel(meta.channels)}
              </>
            )}
          </Typography>
        </Box>
        <IconButton
          size="small"
          onClick={() => onFileSelect(null)}
          sx={{ color: 'text.secondary' }}
        >
          <CloseIcon fontSize="small" />
        </IconButton>
      </Box>
    )
  }

  return (
    <Box
      onClick={() => fileInputRef.current?.click()}
      onDrop={handleDrop}
      onDragOver={handleDragOver}
      onDragLeave={handleDragLeave}
      sx={{
        border: '2px dashed',
        borderColor: dragOver ? 'primary.main' : 'divider',
        borderRadius: 2,
        py: 5,
        px: 2,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        gap: 1,
        cursor: 'pointer',
        transition: 'border-color 0.2s, background-color 0.2s',
        backgroundColor: dragOver ? 'rgba(245, 158, 11, 0.04)' : 'transparent',
        '&:hover': {
          borderColor: 'primary.dark',
          backgroundColor: 'rgba(245, 158, 11, 0.02)',
        },
      }}
    >
      <input
        ref={fileInputRef}
        type="file"
        accept="audio/*"
        onChange={handleFileChange}
        style={{ display: 'none' }}
      />
      <AudioFileIcon sx={{ fontSize: 48, color: 'text.secondary', opacity: 0.5 }} />
      <Typography variant="body1" color="text.secondary" sx={{ fontWeight: 500 }}>
        Drop audio file here, paste from clipboard
      </Typography>
      <Typography variant="caption" color="text.secondary">
        or click to browse
      </Typography>
    </Box>
  )
}

export default FileUploader
