import { useEffect, useRef, useState } from 'react'

export default function useWaveform(canvasRef, audioUrl, isOriginal, color = '#f59e0b', currentTime, duration, positionLineColor = '#fff') {
  const peaksRef = useRef(null)
  const [version, setVersion] = useState(0)

  useEffect(() => {
    if (!audioUrl || !canvasRef.current) return
    const canvas = canvasRef.current
    let cancelled = false

    const compute = async () => {
      try {
        const ac = new AudioContext()
        const resp = await fetch(audioUrl)
        const buf = await resp.arrayBuffer()
        const data = await ac.decodeAudioData(buf)
        ac.close()

        if (cancelled) return

        const channel = data.getChannelData(0)
        const w = canvas.width
        const step = Math.ceil(channel.length / w)
        const peaks = []
        for (let i = 0; i < w; i++) {
          let max = 0
          for (let j = 0; j < step && i * step + j < channel.length; j++) {
            const abs = Math.abs(channel[i * step + j])
            if (abs > max) max = abs
          }
          peaks.push(max)
        }
        peaksRef.current = peaks
        setVersion(v => v + 1)
      } catch (e) { /* ignore */ }
    }
    compute()
    return () => { cancelled = true }
  }, [audioUrl])

  useEffect(() => {
    if (!version || !canvasRef.current) return
    const canvas = canvasRef.current
    const ctx = canvas.getContext('2d')
    const peaks = peaksRef.current
    if (!peaks) return

    const w = canvas.width
    const h = canvas.height
    ctx.clearRect(0, 0, w, h)

    ctx.fillStyle = isOriginal ? '#555' : color
    const mid = h / 2
    for (let i = 0; i < peaks.length; i++) {
      const barH = Math.max(1, peaks[i] * mid)
      ctx.fillRect(i, mid - barH, 1, barH * 2)
    }

    if (duration > 0) {
      const pos = (currentTime / duration) * w
      ctx.strokeStyle = positionLineColor
      ctx.lineWidth = 1.5
      ctx.beginPath()
      ctx.moveTo(pos, 0)
      ctx.lineTo(pos, h)
      ctx.stroke()
    }
  }, [version, isOriginal, color, currentTime, duration, positionLineColor])
}
