import React, { useState, useEffect, useCallback } from 'react'
import { Box, Paper } from '@mui/material'
import { FFmpeg } from '@ffmpeg/ffmpeg'
import { toBlobURL } from '@ffmpeg/util'
import getHLDSP from './hldspLoader'
import { formats, bitrates, roomTypes, mimeTypes } from './constants'
import AppHeader from './components/AppHeader'
import FileUploader from './components/FileUploader'
import RoomTypeSelector from './components/RoomTypeSelector'
import OutputSettings from './components/OutputSettings'
import ProcessingButton from './components/ProcessingButton'
import ProcessingSteps from './components/ProcessingSteps'
import AudioPlayer from './components/AudioPlayer'
import StatusSnackbar from './components/StatusSnackbar'
import LoadingDialog from './components/LoadingDialog'

const ffmpeg = new FFmpeg()

const AudioConverter = ({ mode, onToggleMode }) => {
  const [file, setFile] = useState(null)
  const [format, setFormat] = useState(formats[0])
  const [bitrate, setBitrate] = useState(bitrates[4])
  const [roomType, setRoomType] = useState(roomTypes[0])
  const [openSnackbar, setOpenSnackbar] = useState(false)
  const [snackbarMessage, setSnackbarMessage] = useState('')
  const [ffmpegLoaded, setFFmpegLoaded] = useState(false)
  const [hldspLoaded, setHLDSPLoaded] = useState(false)
  const [loading, setLoading] = useState(true)
  const [loadingMessage, setLoadingMessage] = useState('')
  const [step, setStep] = useState('idle')
  const [previewUrl, setPreviewUrl] = useState(null)
  const [downloadUrl, setDownloadUrl] = useState(null)
  const [downloadName, setDownloadName] = useState('')
  const [fileMeta, setFileMeta] = useState(null)
  const [logs, setLogs] = useState('')

  useEffect(() => {
    const loadModules = async () => {
      ffmpeg.on('log', ({ message }) => {
        console.log(message)
        setLogs((prevLogs) => `${prevLogs}\n${message}`)
      })

      setLoadingMessage('Loading FFmpeg modules...')

      const baseURL = 'https://unpkg.com/@ffmpeg/core@0.12.10/dist/umd'
      await ffmpeg.load({
        coreURL: await toBlobURL(`${baseURL}/ffmpeg-core.js`, 'text/javascript'),
        wasmURL: await toBlobURL(`${baseURL}/ffmpeg-core.wasm`, 'application/wasm'),
      })

      setFFmpegLoaded(true)
      setLoadingMessage('Loading HLDSP module...')

      await getHLDSP()

      setHLDSPLoaded(true)
      setLoading(false)
    }
    loadModules()
    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl)
      if (downloadUrl) URL.revokeObjectURL(downloadUrl)
    }
  }, [])

  const handleFile = useCallback(async (f) => {
    setFile(f)
    setStep('idle')
    setLogs('')
    setPreviewUrl(null)
    setDownloadUrl(null)
    setFileMeta(null)

    if (f) {
      try {
        const ac = new AudioContext()
        const buf = await f.arrayBuffer()
        const data = await ac.decodeAudioData(buf)
        ac.close()
        setFileMeta({
          duration: data.duration,
          sampleRate: data.sampleRate,
          channels: data.numberOfChannels,
        })
      } catch {
        // metadata unavailable, just show name + size
      }
    }
  }, [])

  const handleFormatChange = (event) => setFormat(event.target.value)
  const handleBitrateChange = (event) => setBitrate(event.target.value)
  const handleRoomTypeChange = (event) => setRoomType(event.target.value)

  const handleConvert = async () => {
    if (!file) {
      setSnackbarMessage('Please select an audio file.')
      setOpenSnackbar(true)
      return
    }

    setLogs('')

    try {
      const data = await file.arrayBuffer()
      const inputData = new Uint8Array(data)
      const baseName = file.name.replace(/\.[^.]+$/, '')
      const outputFileName = `${baseName}-hldsp.${format.extension}`

      setStep('wav')
      setSnackbarMessage('Converting to WAV...')
      setOpenSnackbar(true)

      await ffmpeg.writeFile(file.name, inputData)
      await ffmpeg.exec(['-i', file.name, '-c:a', 'pcm_s16le', '-ar', '44100', '-ac', '2', 'temp.wav'])
      const wavData = await ffmpeg.readFile('temp.wav')

      setStep('dsp')
      setSnackbarMessage(`Applying DSP effects (${roomType.title})...`)
      setOpenSnackbar(true)

      const hldsp = await getHLDSP()
      hldsp.FS.writeFile('/input.wav', new Uint8Array(wavData))
      const result = hldsp._hldsp_process(roomType.index)
      if (result !== 0) {
        hldsp.FS.unlink('/input.wav')
        throw new Error('DSP processing failed.')
      }
      const processedWav = hldsp.FS.readFile('/output.wav')
      hldsp.FS.unlink('/input.wav')
      hldsp.FS.unlink('/output.wav')

      setStep('encode')
      setSnackbarMessage(`Converting to ${format.title}...`)
      setOpenSnackbar(true)

      await ffmpeg.writeFile('processed.wav', processedWav)
      await ffmpeg.exec(['-i', 'processed.wav', '-c:a', format.codec, '-b:a', bitrate.value, outputFileName])
      const outputData = await ffmpeg.readFile(outputFileName)

      if (previewUrl) URL.revokeObjectURL(previewUrl)
      if (downloadUrl) URL.revokeObjectURL(downloadUrl)
      setPreviewUrl(URL.createObjectURL(new Blob([outputData], { type: mimeTypes[format.extension] })))
      setDownloadUrl(URL.createObjectURL(new Blob([outputData], { type: mimeTypes[format.extension] })))
      setDownloadName(outputFileName)

      try { await ffmpeg.deleteFile(file.name) } catch (e) { /* ignore */ }
      try { await ffmpeg.deleteFile('temp.wav') } catch (e) { /* ignore */ }
      try { await ffmpeg.deleteFile('processed.wav') } catch (e) { /* ignore */ }
      try { await ffmpeg.deleteFile(outputFileName) } catch (e) { /* ignore */ }

      setStep('done')
      setSnackbarMessage('Conversion finished.')
      setOpenSnackbar(true)
    } catch (e) {
      setStep('error')
      setSnackbarMessage(e.message || 'Processing failed.')
      setOpenSnackbar(true)
    }
  }

  const handleCloseSnackbar = () => setOpenSnackbar(false)

  return (
    <Box sx={{ minHeight: '100dvh', py: { xs: 2, sm: 4 } }}>
      <Box sx={{ maxWidth: 640, mx: 'auto', px: { xs: 1.5, sm: 2 } }}>
        <AppHeader mode={mode} onToggleMode={onToggleMode} />

        <LoadingDialog open={loading} message={loadingMessage} />

        <Paper sx={{ p: { xs: 2, sm: 3 }, mb: 2 }}>
          <FileUploader file={file} meta={fileMeta} onFileSelect={handleFile} />
        </Paper>

        <Paper sx={{ p: { xs: 2, sm: 3 }, mb: 2 }}>
          <RoomTypeSelector value={roomType} onChange={handleRoomTypeChange} />
          <OutputSettings
            format={format}
            bitrate={bitrate}
            onFormatChange={handleFormatChange}
            onBitrateChange={handleBitrateChange}
          />
        </Paper>

        <Paper sx={{ p: { xs: 2, sm: 3 }, mb: 2 }}>
          <ProcessingButton
            processing={step !== 'idle' && step !== 'done' && step !== 'error'}
            message={snackbarMessage}
            onClick={handleConvert}
            disabled={!(ffmpegLoaded && hldspLoaded && (step === 'idle' || step === 'done' || step === 'error'))}
          />
          <ProcessingSteps step={step} logs={logs} />
        </Paper>

        {previewUrl && (
          <Paper sx={{ p: { xs: 2, sm: 3 }, mb: 2 }}>
            <AudioPlayer
              previewUrl={previewUrl}
              downloadUrl={downloadUrl}
              downloadName={downloadName}
            />
          </Paper>
        )}
      </Box>

      <StatusSnackbar
        open={openSnackbar}
        message={snackbarMessage}
        onClose={handleCloseSnackbar}
      />
    </Box>
  )
}

export default AudioConverter
