import React, { useRef, useState, useEffect } from 'react'
import { Box, Typography, Slider, IconButton, Button } from '@mui/material'
import { useTheme } from '@mui/material/styles'
import PlayArrowIcon from '@mui/icons-material/PlayArrow'
import StopIcon from '@mui/icons-material/Stop'
import DownloadIcon from '@mui/icons-material/Download'
import { formatTime } from '../utils'
import useWaveform from '../hooks/useWaveform'

const AudioPlayer = ({ previewUrl, downloadUrl, downloadName }) => {
  const [currentTime, setCurrentTime] = useState(0)
  const [duration, setDuration] = useState(0)
  const audioRef = useRef(null)
  const canvasRef = useRef(null)
  const theme = useTheme()
  const rafRef = useRef(null)

  const positionLineColor = theme.palette.mode === 'dark' ? '#ffffff' : '#1a1a1a'
  useWaveform(canvasRef, previewUrl, false, theme.palette.primary.main, currentTime, duration, positionLineColor)

  useEffect(() => {
    const audio = audioRef.current
    if (!audio) return

    const tick = () => {
      setCurrentTime(audio.currentTime)
      rafRef.current = requestAnimationFrame(tick)
    }

    const start = () => { rafRef.current = requestAnimationFrame(tick) }
    const stop = () => { cancelAnimationFrame(rafRef.current) }

    audio.addEventListener('play', start)
    audio.addEventListener('pause', stop)
    audio.addEventListener('ended', stop)

    return () => {
      cancelAnimationFrame(rafRef.current)
      audio.removeEventListener('play', start)
      audio.removeEventListener('pause', stop)
      audio.removeEventListener('ended', stop)
    }
  }, [previewUrl])

  return (
    <Box>
      <audio
        ref={audioRef}
        src={previewUrl}
        onLoadedMetadata={() => setDuration(audioRef.current.duration)}
        onEnded={() => setCurrentTime(0)}
      />
      <canvas
        ref={canvasRef}
        style={{ width: '100%', height: 'auto', display: 'block', borderRadius: 6, aspectRatio: '10 / 1' }}
        width={800}
        height={80}
      />
      <Box sx={{
        display: 'flex',
        alignItems: 'center',
        gap: { xs: 0.25, sm: 0.5 },
        mt: 1.5,
        flexWrap: 'wrap',
        justifyContent: 'center',
      }}>
        <Box sx={{
          display: 'flex',
          alignItems: 'center',
          gap: 0.5,
          flex: { xs: '1 1 100%', sm: 1 },
        }}>
          <Typography variant="caption" sx={{ minWidth: 28, textAlign: 'left', fontSize: { xs: '0.65rem', sm: '0.75rem' }, color: 'text.secondary' }}>
            {formatTime(currentTime)}
          </Typography>
          <Slider
            value={currentTime}
            max={duration || 1}
            step={0.01}
            onChange={(_, v) => { audioRef.current.currentTime = v; setCurrentTime(v) }}
            sx={{ flex: 1, color: 'primary.main' }}
            size="small"
          />
          <Typography variant="caption" sx={{ minWidth: 28, textAlign: 'right', fontSize: { xs: '0.65rem', sm: '0.75rem' }, color: 'text.secondary' }}>
            {formatTime(duration)}
          </Typography>
        </Box>
        <IconButton size="small" color="primary" onClick={() => audioRef.current.play()}>
          <PlayArrowIcon fontSize="small" />
        </IconButton>
        <IconButton
          size="small"
          color="primary"
          onClick={() => { audioRef.current.pause(); audioRef.current.currentTime = 0; setCurrentTime(0) }}
        >
          <StopIcon fontSize="small" />
        </IconButton>
      </Box>
      <Button
        variant="contained"
        color="primary"
        fullWidth
        size="large"
        startIcon={<DownloadIcon />}
        sx={{ mt: 1.5, py: 1.2 }}
        onClick={() => {
          const a = document.createElement('a')
          a.href = downloadUrl
          a.download = downloadName
          a.click()
        }}
      >
        Download processed audio
      </Button>
    </Box>
  )
}

export default AudioPlayer
